typedef long long ll;

typedef struct {
    ll x, y;
} Point;

static int cmp_point(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return 0;
}

static ll cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static int build_hull(Point *pts, int n, Point *hull) {
    if (n == 0) return 0;
    qsort(pts, n, sizeof(Point), cmp_point);

    int m = 0;
    for (int i = 0; i < n; i++) {
        while (m >= 2 && cross(hull[m - 2], hull[m - 1], pts[i]) <= 0) m--;
        hull[m++] = pts[i];
    }
    int lower = m;
    for (int i = n - 2; i >= 0; i--) {
        while (m > lower && cross(hull[m - 2], hull[m - 1], pts[i]) <= 0) m--;
        hull[m++] = pts[i];
    }
    if (n > 1) m--;
    return m;
}

static int on_segment(Point a, Point b, Point p) {
    if (cross(a, b, p) != 0) return 0;
    if (p.x < (a.x < b.x ? a.x : b.x) || p.x > (a.x > b.x ? a.x : b.x)) return 0;
    if (p.y < (a.y < b.y ? a.y : b.y) || p.y > (a.y > b.y ? a.y : b.y)) return 0;
    return 1;
}

static int segments_intersect(Point a, Point b, Point c, Point d) {
    ll c1 = cross(a, b, c);
    ll c2 = cross(a, b, d);
    ll c3 = cross(c, d, a);
    ll c4 = cross(c, d, b);

    if ((c1 > 0 && c2 < 0 || c1 < 0 && c2 > 0) &&
        (c3 > 0 && c4 < 0 || c3 < 0 && c4 > 0))
        return 1;

    if (c1 == 0 && on_segment(a, b, c)) return 1;
    if (c2 == 0 && on_segment(a, b, d)) return 1;
    if (c3 == 0 && on_segment(c, d, a)) return 1;
    if (c4 == 0 && on_segment(c, d, b)) return 1;

    return 0;
}

static int point_in_convex_or_boundary(Point *poly, int n, Point p) {
    if (n == 0) return 0;
    if (n == 1) return poly[0].x == p.x && poly[0].y == p.y;
    if (n == 2) return on_segment(poly[0], poly[1], p);

    for (int i = 0; i < n; i++) {
        Point a = poly[i];
        Point b = poly[(i + 1) % n];
        if (cross(a, b, p) < 0) return 0;
    }
    return 1;
}

static int hulls_intersect(Point *A, int nA, Point *B, int nB) {
    if (nA == 0 || nB == 0) return 0;

    if (nA == 1 && nB == 1) {
        return A[0].x == B[0].x && A[0].y == B[0].y;
    }

    if (nA == 1) return point_in_convex_or_boundary(B, nB, A[0]);
    if (nB == 1) return point_in_convex_or_boundary(A, nA, B[0]);

    for (int i = 0; i < nA; i++) {
        Point a1 = A[i];
        Point a2 = A[(i + 1) % nA];
        for (int j = 0; j < nB; j++) {
            Point b1 = B[j];
            Point b2 = B[(j + 1) % nB];
            if (segments_intersect(a1, a2, b1, b2)) return 1;
        }
    }

    if (point_in_convex_or_boundary(A, nA, B[0])) return 1;
    if (point_in_convex_or_boundary(B, nB, A[0])) return 1;

    return 0;
}

