bool isSeparable(vector<Point>& pts) {
    int n = pts.size();
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int side = 0;
            bool ok = true;
            for (int k = 0; k < n; ++k) {
                if (k == i || k == j) continue;
                int c = cross(pts[i], pts[j], pts[k]);
                if (c == 0) continue;
                int s = (c > 0) ? 1 : -1;
                if (side == 0) side = s;
                else if (side != s) { ok = false; break; }
            }
            if (!ok) continue;
            // Check if all black are on one side and white on the other
            int blackSide = 0, whiteSide = 0;
            for (int k = 0; k < n; ++k) {
                if (k == i || k == j) continue;
                int c = cross(pts[i], pts[j], pts[k]);
                if (c == 0) continue;
                int s = (c > 0) ? 1 : -1;
                if (pts[k].color == 0) blackSide = s;
                else whiteSide = s;
            }
            if (blackSide != 0 && whiteSide != 0 && blackSide != whiteSide)
                return true;
            // also handle case where one color is on the line
            bool blackOnLine = false, whiteOnLine = false;
            for (int k = 0; k < n; ++k) {
                if (k == i || k == j) continue;
                int c = cross(pts[i], pts[j], pts[k]);
                if (c == 0) {
                    if (pts[k].color == 0) blackOnLine = true;
                    else whiteOnLine = true;
                }
            }
            if (!blackOnLine && !whiteOnLine) continue;
            if (blackOnLine && whiteOnLine) continue;
            if (blackOnLine && whiteSide != 0) return true;
            if (whiteOnLine && blackSide != 0) return true;
        }
    }
    // also check trivial case: all points same color
    int blackCount = 0, whiteCount = 0;
    for (auto& p : pts) {
        if (p.color == 0) blackCount++;
        else whiteCount++;
    }
    if (blackCount == 0 || whiteCount == 0) return true;
    return false;
}

