};

static const double EPS = 1e-10;

double cross(const Point& a, const Point& b, const Point& c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

bool onSegment(const Point& a, const Point& b, const Point& p) {
    return fabs(cross(a, b, p)) < EPS &&
           min(a.x, b.x) - EPS <= p.x && p.x <= max(a.x, b.x) + EPS &&
           min(a.y, b.y) - EPS <= p.y && p.y <= max(a.y, b.y) + EPS;
}

vector<Point> convexHull(vector<Point> pts) {
    int n = (int)pts.size();
    if (n <= 1) return pts;

    sort(pts.begin(), pts.end(), [](const Point& a, const Point& b) {
        if (fabs(a.x - b.x) > EPS) return a.x < b.x;
        return a.y < b.y;
    });

    vector<Point> lower, upper;
    for (auto &p : pts) {
        while (lower.size() >= 2 &&
               cross(lower[lower.size()-2], lower.back(), p) <= EPS)
            lower.pop_back();
        lower.push_back(p);
    }
    for (int i = n - 1; i >= 0; --i) {
        auto &p = pts[i];
        while (upper.size() >= 2 &&
               cross(upper[upper.size()-2], upper.back(), p) <= EPS)
            upper.pop_back();
        upper.push_back(p);
    }

    lower.pop_back();
    upper.pop_back();
    lower.insert(lower.end(), upper.begin(), upper.end());

    if (lower.empty()) lower.push_back(pts[0]);
    return lower;
}

int sgn(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

bool pointInConvex(const vector<Point>& poly, const Point& p) {
    int n = (int)poly.size();
    if (n == 0) return false;
    if (n == 1) {
        return fabs(poly[0].x - p.x) < EPS && fabs(poly[0].y - p.y) < EPS;
    }
    if (n == 2) {
        return onSegment(poly[0], poly[1], p);
    }

    int sign = 0;
    for (int i = 0; i < n; ++i) {
        double cr = cross(poly[i], poly[(i+1)%n], p);
        int s = sgn(cr);
        if (s == 0) continue;
        if (sign == 0) sign = s;
        else if (sign != s) return false;
    }
    return true;
}

bool segmentsIntersect(const Point& a, const Point& b, const Point& c, const Point& d) {
    double c1 = cross(a, b, c);
    double c2 = cross(a, b, d);
    double c3 = cross(c, d, a);
    double c4 = cross(c, d, b);

    int s1 = sgn(c1), s2 = sgn(c2), s3 = sgn(c3), s4 = sgn(c4);

    if (s1 * s2 < 0 && s3 * s4 < 0) return true;
    if (s1 == 0 && onSegment(a, b, c)) return true;
    if (s2 == 0 && onSegment(a, b, d)) return true;
    if (s3 == 0 && onSegment(c, d, a)) return true;
    if (s4 == 0 && onSegment(c, d, b)) return true;
    return false;
}

bool hullsIntersect(const vector<Point>& A, const vector<Point>& B) {
    int n = (int)A.size(), m = (int)B.size();
    if (n == 0 || m == 0) return false;

    if (n == 1 && m == 1) {
        return fabs(A[0].x - B[0].x) < EPS && fabs(A[0].y - B[0].y) < EPS;
    }

    if (n == 1) return pointInConvex(B, A[0]);
    if (m == 1) return pointInConvex(A, B[0]);

    for (int i = 0; i < n; ++i) {
        Point a1 = A[i], a2 = A[(i+1)%n];
        for (int j = 0; j < m; ++j) {
            Point b1 = B[j], b2 = B[(j+1)%m];
            if (segmentsIntersect(a1, a2, b1, b2)) return true;
        }
    }

    if (pointInConvex(A, B[0])) return true;
    if (pointInConvex(B, A[0])) return true;

    return false;
}

