def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points):
    points = sorted(set(points))
    n = len(points)
    if n <= 1:
        return points

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def on_segment(a, b, p):
    return cross(a, b, p) == 0 and min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

def segments_intersect(a, b, c, d):
    c1 = cross(a, b, c)
    c2 = cross(a, b, d)
    c3 = cross(c, d, a)
    c4 = cross(c, d, b)

    if c1 == 0 and on_segment(a, b, c):
        return True
    if c2 == 0 and on_segment(a, b, d):
        return True
    if c3 == 0 and on_segment(c, d, a):
        return True
    if c4 == 0 and on_segment(c, d, b):
        return True

    return (c1 > 0) != (c2 > 0) and (c3 > 0) != (c4 > 0)

def point_in_convex(poly, p):
    n = len(poly)
    if n == 0:
        return False
    if n == 1:
        return poly[0] == p
    if n == 2:
        return on_segment(poly[0], poly[1], p)

    sign = 0
    for i in range(n):
        a = poly[i]
        b = poly[(i + 1) % n]
        c = cross(a, b, p)
        if c == 0:
            if on_segment(a, b, p):
                return True
            continue
        if sign == 0:
            sign = 1 if c > 0 else -1
        elif (c > 0 and sign < 0) or (c < 0 and sign > 0):
            return False
    return True

def hulls_intersect(h1, h2):
    if not h1 or not h2:
        return False

    n1, n2 = len(h1), len(h2)

    if n1 == 1 and n2 == 1:
        return h1[0] == h2[0]
    if n1 == 1:
        return point_in_convex(h2, h1[0])
    if n2 == 1:
        return point_in_convex(h1, h2[0])

    edges1 = [(h1[i], h1[(i + 1) % n1]) for i in range(n1)] if n1 >= 3 else [(h1[0], h1[1])]
    edges2 = [(h2[i], h2[(i + 1) % n2]) for i in range(n2)] if n2 >= 3 else [(h2[0], h2[1])]

    for a, b in edges1:
        for c, d in edges2:
            if segments_intersect(a, b, c, d):
                return True

    if point_in_convex(h1, h2[0]):
        return True
    if point_in_convex(h2, h1[0]):
        return True

