public class Main {
    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    // Cross product of (b-a) and (c-a)
    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    // Convex hull using monotone chain
    static List<Point> convexHull(List<Point> points) {
        int n = points.size();
        if (n <= 1) return new ArrayList<>(points);
        points.sort((p, q) -> p.x != q.x ? Long.compare(p.x, q.x) : Long.compare(p.y, q.y));
        List<Point> hull = new ArrayList<>();
        // lower hull
        for (Point p : points) {
            while (hull.size() >= 2 && cross(hull.get(hull.size()-2), hull.get(hull.size()-1), p) <= 0)
                hull.remove(hull.size()-1);
            hull.add(p);
        }
        // upper hull
        int lowerLen = hull.size();
        for (int i = n-2; i >= 0; i--) {
            Point p = points.get(i);
            while (hull.size() > lowerLen && cross(hull.get(hull.size()-2), hull.get(hull.size()-1), p) <= 0)
                hull.remove(hull.size()-1);
            hull.add(p);
        }
        hull.remove(hull.size()-1); // remove duplicate first point
        return hull;
    }

    // Check if point p is inside convex polygon (strictly)
    static boolean pointInConvexPolygon(List<Point> hull, Point p) {
        int n = hull.size();
        if (n == 0) return false;
        if (n == 1) return hull.get(0).x == p.x && hull.get(0).y == p.y;
        if (n == 2) {
            return cross(hull.get(0), hull.get(1), p) == 0 &&
                   Math.min(hull.get(0).x, hull.get(1).x) <= p.x &&
                   p.x <= Math.max(hull.get(0).x, hull.get(1).x) &&
                   Math.min(hull.get(0).y, hull.get(1).y) <= p.y &&
                   p.y <= Math.max(hull.get(0).y, hull.get(1).y);
        }
        for (int i = 0; i < n; i++) {
            Point a = hull.get(i);
            Point b = hull.get((i+1)%n);
            if (cross(a, b, p) <= 0) return false;
        }
        return true;
    }

    // Check if two convex polygons intersect (including boundaries)
    static boolean hullsIntersect(List<Point> A, List<Point> B) {
        for (Point p : B) {
            if (pointInConvexPolygon(A, p)) return true;
        }
        for (Point p : A) {
            if (pointInConvexPolygon(B, p)) return true;
        }
        int n = A.size(), m = B.size();
        for (int i = 0; i < n; i++) {
            Point a1 = A.get(i), a2 = A.get((i+1)%n);
            for (int j = 0; j < m; j++) {
                Point b1 = B.get(j), b2 = B.get((j+1)%m);
                if (segmentsIntersect(a1, a2, b1, b2)) return true;
            }
        }
        return false;
    }

    static boolean segmentsIntersect(Point p1, Point p2, Point q1, Point q2) {
        long o1 = cross(p1, p2, q1);
        long o2 = cross(p1, p2, q2);
        long o3 = cross(q1, q2, p1);
        long o4 = cross(q1, q2, p2);
        if (o1 == 0 && onSegment(p1, p2, q1)) return true;
        if (o2 == 0 && onSegment(p1, p2, q2)) return true;
        if (o3 == 0 && onSegment(q1, q2, p1)) return true;
        if (o4 == 0 && onSegment(q1, q2, p2)) return true;
        return (o1 > 0) != (o2 > 0) && (o3 > 0) != (o4 > 0);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        return Math.min(a.x, b.x) <= p.x && p.x <= Math.max(a.x, b.x) &&
               Math.min(a.y, b.y) <= p.y && p.y <= Math.max(a.y, b.y);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        List<Point> black = new ArrayList<>();
        List<Point> white = new ArrayList<>();
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            long x = Long.parseLong(parts[0]);
            long y = Long.parseLong(parts[1]);
            String color = parts[2];
            if (color.equals("B")) {
                black.add(new Point(x, y));
            } else {
                white.add(new Point(x, y));
            }
        }

        if (black.isEmpty() || white.isEmpty()) {
            System.out.println("YES");
            return;
        }

        List<Point> hullBlack = convexHull(black);
        List<Point> hullWhite = convexHull(white);

        if (hullsIntersect(hullBlack, hullWhite)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }
}

