import java.io.*;
import java.util.*;

/*
We need to determine whether two finite point sets (black and white) in the plane
can be strictly separated by a straight line.

A standard theorem: two finite point sets are linearly separable iff their convex
hulls do not intersect. Also, if one hull contains a point of the other color, they
are not separable.

So:
1) Read all black and white points.
2) Build convex hulls of both sets.
3) Check whether the two convex polygons intersect:
   - any edge pairs intersect
   - or one polygon contains a point of the other
If they intersect/touch => not separable.
Otherwise => separable.

This solution supports multiple test cases until EOF.
Expected input format:
n m
x1 y1   (n black points)
...
x y
x1 y1   (m white points)
...
If your judge uses another but equivalent EOF-based format, this parser still works.
*/

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Point implements Comparable<Point> {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public int compareTo(Point o) {
            if (x != o.x) return Long.compare(x, o.x);
            return Long.compare(y, o.y);
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        if (cross(a, b, p) != 0) return false;
        return Math.min(a.x, b.x) <= p.x && p.x <= Math.max(a.x, b.x)
            && Math.min(a.y, b.y) <= p.y && p.y <= Math.max(a.y, b.y);
    }

    static int sgn(long x) {
        return Long.compare(x, 0);
    }

    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        long c1 = cross(a, b, c);
        long c2 = cross(a, b, d);
        long c3 = cross(c, d, a);
        long c4 = cross(c, d, b);

        int s1 = sgn(c1), s2 = sgn(c2), s3 = sgn(c3), s4 = sgn(c4);

        if (s1 == 0 && onSegment(a, b, c)) return true;
        if (s2 == 0 && onSegment(a, b, d)) return true;
        if (s3 == 0 && onSegment(c, d, a)) return true;
        if (s4 == 0 && onSegment(c, d, b)) return true;

        return s1 * s2 < 0 && s3 * s4 < 0;
    }

    static List<Point> convexHull(List<Point> pts) {
        List<Point> p = new ArrayList<>(pts);
        Collections.sort(p);

        // remove duplicates
        List<Point> uniq = new ArrayList<>();
        for (Point pt : p) {
            if (uniq.isEmpty() || uniq.get(uniq.size() - 1).x != pt.x || uniq.get(uniq.size() - 1).y != pt.y) {
                uniq.add(pt);
            }
        }
        p = uniq;

        int n = p.size();
        if (n <= 1) return p;

        List<Point> lower = new ArrayList<>();
        for (Point pt : p) {
            while (lower.size() >= 2 &&
                    cross(lower.get(lower.size() - 2), lower.get(lower.size() - 1), pt) <= 0) {
                lower.remove(lower.size() - 1);
            }
            lower.add(pt);
        }

        List<Point> upper = new ArrayList<>();
        for (int i = n - 1; i >= 0; i--) {
            Point pt = p.get(i);
            while (upper.size() >= 2 &&
                    cross(upper.get(upper.size() - 2), upper.get(upper.size() - 1), pt) <= 0) {
                upper.remove(upper.size() - 1);
            }
            upper.add(pt);
        }

        lower.remove(lower.size() - 1);
        upper.remove(upper.size() - 1);
        lower.addAll(upper);
        return lower;
    }

    static boolean pointInConvexOrBoundary(Point p, List<Point> poly) {
        int n = poly.size();
        if (n == 0) return false;
        if (n == 1) {
            return poly.get(0).x == p.x && poly.get(0).y == p.y;
        }
        if (n == 2) {
            return onSegment(poly.get(0), poly.get(1), p);
        }

        boolean pos = false, neg = false;
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i + 1) % n);
            long cr = cross(a, b, p);
            if (cr > 0) pos = true;
            if (cr < 0) neg = true;
            if (pos && neg) return false;
        }
        return true; // inside or on boundary
    }

    static boolean hullsIntersect(List<Point> A, List<Point> B) {
        int n = A.size(), m = B.size();

        if (n == 0 || m == 0) return false;

        if (n == 1 && m == 1) {
            return A.get(0).x == B.get(0).x && A.get(0).y == B.get(0).y;
        }

        if (n == 1) {
            return pointInConvexOrBoundary(A.get(0), B);
        }
        if (m == 1) {
            return pointInConvexOrBoundary(B.get(0), A);
        }

        for (int i = 0; i < n; i++) {
            Point a1 = A.get(i);
            Point a2 = A.get((i + 1) % n);
            for (int j = 0; j < m; j++) {
                Point b1 = B.get(j);
                Point b2 = B.get((j + 1) % m);
                if (segmentsIntersect(a1, a2, b1, b2)) return true;
            }
        }

        if (pointInConvexOrBoundary(A.get(0), B)) return true;
        if (pointInConvexOrBoundary(B.get(0), A)) return true;

        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            Integer nObj = fs.nextInt();
            if (nObj == null) break;
            Integer mObj = fs.nextInt();
            if (mObj == null) break;

            int n = nObj, m = mObj;

            List<Point> black = new ArrayList<>();
            List<Point> white = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                long x = fs.nextInt();
                long y = fs.nextInt();
                black.add(new Point(x, y));
            }
            for (int i = 0; i < m; i++) {
                long x = fs.nextInt();
                long y = fs.nextInt();
                white.add(new Point(x, y));
            }

            List<Point> hullB = convexHull(black);
            List<Point> hullW = convexHull(white);

            boolean separable = !hullsIntersect(hullB, hullW);
            out.append(separable ? "YES" : "NO").append('\n');
        }

        System.out.print(out.toString());
    }
